import pathlib,hashlib,json
base=pathlib.Path(__file__).resolve().parent; root=base.parents[1]
groups={
'scripts/audit_reconstruction_precision.py':[(1,10,'توثيق ومكتبات قياسية وخارجية لتدقيق حساسية FP64، ووظائف التحويل والمقاييس والبصمة الداخلية.'),(13,18,'main تقرأ مجلد التحقق ثم تنبؤاته المحفوظة بدقة round_trip وتبدأ قوائم المقارنة والجداول.'),(19,24,'لكل تصميم وهدف وأصل ونموذج ترتب التواريخ وتنسخ الجدول وتحفظ التنبؤ الأصلي وتعيد تركيب السعر بعد تحويل الهدف والسعر الحالي إلى float64. هذه حساسية حسابية منفصلة لا تعيد تدريباً.'),(25,28,'تحسب مقاييس قبل وبعد وتجمع الهوية وأعظم فرق سعر وفرق RMSE وعدد تغيرات إشارة التوقع. الحساب يقرأ التنبؤ المحفوظ ولا يثبت جودة النموذج.'),(29,33,'تكتب ملفات مقارنة وتنبؤات ومقاييس FP64 منفصلة مع بصمة الأصل والمنشأ وتطبع الفروق؛ التنفيذ يعدل آثار التحقق ولم يُشغّل هنا.'),(36,37,'حارس التنفيذ يستدعي main.')],
'scripts/diagnose_validation_replay.py':[(1,12,'توثيق واستيرادات قراءة ونماذج LSTM ونوافذ وبذور وتخزين؛ يتطلب torch وCUDA ضمن load_lstm.'),(15,20,'main تقرأ مجلد التحقق وتضبط البذرة وتبدأ نتائج التشخيص.'),(21,28,'تمر على design.json للمهام وتحمل نوافذ المصدر وفهارس الاختبار والتنبؤ المحفوظ والمعايير؛ joblib ينبغي تحميله من مصدر موثوق.'),(29,34,'تحسب التنبؤ ذاته بإعادة تحميل CPU وCUDA وتفرض تطابق GPU والمحفوظه بتاً بت، وتسجل أقصى خطأ CPU بالوحدة الأصلية ومعيار التدريب ثم تكتب JSON وتطبع. يتطلب CUDA ولا يثبت تطابق أجهزة أخرى؛ لم يُنفذ هنا.'),(37,38,'حارس التشغيل يستدعي main.')],
'scripts/offline_smoke.py':[(1,10,'توثيق واستيرادات Path وjson وsocket وAppTest، وتحديد الجذر وحفظ دالة اتصال socket الأصلية.'),(13,16,'loopback_only ترفض عنوان tuple غير localhost ثم تفوض الاتصال الأصلي. لا تغطي وحدها جميع طرق الشبكة أو كل أشكال العنوان.'),(19,26,'تستبدل socket.connect في العملية وتشغل AppTest للواجهة، وتفحص غياب الاستثناء وثمانية تبويبات وتطابق خيارات الأصول مع إعداد التشغيل المحفوظ.'),(27,35,'تختار كل أصل وكل نموذج تفسير وتتحقق من غياب الاستثناء، ثم تختار آخر تاريخ محسوب مسبقاً. حالة أول تاريخ تفترض الاختيار الافتراضي ولا تتحقق صراحة من جميع التواريخ.'),(36,38,'تكتب إيصالاً في artifacts/tests وتطبع النجاح؛ يصف العرض المحفوظ دون تدريب أو اختبار صور متصفح. لم يشغل هنا.')],
'scripts/replicate_validation_lstm.py':[(1,14,'توثيق واستيرادات إعداد وإعادة تدريب LSTM وقراءة النوافذ والهدف والحفظ؛ هذا سكربت تجربة لا توثيق فقط.'),(17,28,'main تقرأ الوجهة والتصميم والبروتوكول وتحول نوافذ AAPL إلى فرق السعر وتخلق مجلد تكرار exist_ok=False وتضبط البذرة. يمنع وجود المجلد إعادة استخدامه.'),(29,35,'تدرب LSTM مع حدود الخيوط وتحفظ scalers وتقارن متوسطاتها ومقاييسها وتباينها مع المرجع. إعادة التدريب تغير آثاراً ولم تُنفذ هنا.'),(36,45,'تحمل مرجعاً على نوع جهاز التكرار وتقارن تنبؤات الاختبار بتاً بت ثم تقارن طول التاريخ وكل epoch وخسارة تدريب وتحقق. لا تقارن الزمن وتفترض إمكانية إعادة إنتاج البيئة.'),(46,47,'تكتب إيصال المقارنة وتطبع النتيجة؛ النطاق تجربة AAPL واحدة على بيئة محددة، لا برهان استقرار متعدد البذور.'),(50,51,'حارس التنفيذ يستدعي main.')]
}
manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); digest=hashlib.sha256(raw).hexdigest(); name=path.replace('/','_')+'.md'; out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','لم يُشغّل السكربت في جلسة التوثيق.','']
 for a,b,d in entries: out += [f'## الأسطر {a}–{b}','','```python',*src[a-1:b],'```','',d,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8'); manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'يدوية غير مستقلة','quote_verification':'آلي'}
(base/'replay_smoke_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
